"use strict";(globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init=globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init||[]).push([[64861],{76489(e,a,o){o.r(a),o.d(a,{assets:()=>t,contentTitle:()=>c,default:()=>u,frontMatter:()=>r,metadata:()=>s,toc:()=>l});const s=JSON.parse('{"id":"cursos/solid/modulos/refactorizacion-goal-solid/cuestionario","title":"cuestionario","description":"2. [Investigar] \xbfQu\xe9 es el patr\xf3n \\"Strangler Fig Application\\" (Martin Fowler, 2004) y c\xf3mo se relaciona con la refactorizaci\xf3n incremental hacia SOLID? \xbfPor qu\xe9 es preferible a una reescritura completa incluso si el objetivo final es un sistema completamente nuevo?","source":"@site/docs/cursos/solid/modulos/09-refactorizacion-goal-solid/cuestionario.md","sourceDirName":"cursos/solid/modulos/09-refactorizacion-goal-solid","slug":"/cursos/solid/modulos/refactorizacion-goal-solid/cuestionario","permalink":"/sasf-temarios/cursos/solid/modulos/refactorizacion-goal-solid/cuestionario","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"private":true,"sidebar_class_name":"private","sidebar_label":"Cuestionario"},"sidebar":"cursosSidebar","previous":{"title":"Clase","permalink":"/sasf-temarios/cursos/solid/modulos/refactorizacion-goal-solid/clase"},"next":{"title":"Ejercicio","permalink":"/sasf-temarios/cursos/solid/modulos/refactorizacion-goal-solid/ejercicio"}}');var n=o(74848),i=o(28453);const r={private:!0,sidebar_class_name:"private",sidebar_label:"Cuestionario"},c=void 0,t={},l=[{value:"2. [Investigar] \xbfQu\xe9 es el patr\xf3n &quot;Strangler Fig Application&quot; (Martin Fowler, 2004) y c\xf3mo se relaciona con la refactorizaci\xf3n incremental hacia SOLID? \xbfPor qu\xe9 es preferible a una reescritura completa incluso si el objetivo final es un sistema completamente nuevo?",id:"2-investigar-qu\xe9-es-el-patr\xf3n-strangler-fig-application-martin-fowler-2004-y-c\xf3mo-se-relaciona-con-la-refactorizaci\xf3n-incremental-hacia-solid-por-qu\xe9-es-preferible-a-una-reescritura-completa-incluso-si-el-objetivo-final-es-un-sistema-completamente-nuevo",level:3},{value:"3. [Investigar] J.B. Rainsberger public\xf3 &quot;Integrated Tests Are a Scam&quot; (2015), argumentando que las pruebas de integraci\xf3n son una p\xe9rdida de tiempo comparadas con pruebas unitarias aisladas. \xbfC\xf3mo se conecta este argumento con DIP y SRP? \xbfPor qu\xe9 sin DIP no pod\xe9s escribir pruebas unitarias aisladas que cubran el mismo comportamiento?",id:"3-investigar-jb-rainsberger-public\xf3-integrated-tests-are-a-scam-2015-argumentando-que-las-pruebas-de-integraci\xf3n-son-una-p\xe9rdida-de-tiempo-comparadas-con-pruebas-unitarias-aisladas-c\xf3mo-se-conecta-este-argumento-con-dip-y-srp-por-qu\xe9-sin-dip-no-pod\xe9s-escribir-pruebas-unitarias-aisladas-que-cubran-el-mismo-comportamiento",level:3},{value:"4. [Investigar] \xbfQu\xe9 es &quot;code as a liability&quot; (c\xf3digo como pasivo) y c\xf3mo se relaciona con la decisi\xf3n de refactorizar o no? Investig\xe1 la postura de Greg Young y Alberto Brandolini sobre que el c\xf3digo legacy que funciona es un activo, no un pasivo, y que refactorizar sin necesidad de negocio es una mala inversi\xf3n.",id:"4-investigar-qu\xe9-es-code-as-a-liability-c\xf3digo-como-pasivo-y-c\xf3mo-se-relaciona-con-la-decisi\xf3n-de-refactorizar-o-no-investig\xe1-la-postura-de-greg-young-y-alberto-brandolini-sobre-que-el-c\xf3digo-legacy-que-funciona-es-un-activo-no-un-pasivo-y-que-refactorizar-sin-necesidad-de-negocio-es-una-mala-inversi\xf3n",level:3},{value:"5. [Conectar] Conect\xe1 la refactorizaci\xf3n hacia SOLID con el concepto de &quot;The Boy Scout Rule&quot; de Robert C. Martin. \xbfC\xf3mo esta regla aplicada consistentemente logra transformar un sistema legacy sin un proyecto de refactorizaci\xf3n expl\xedcito? \xbfCu\xe1les son sus limitaciones?",id:"5-conectar-conect\xe1-la-refactorizaci\xf3n-hacia-solid-con-el-concepto-de-the-boy-scout-rule-de-robert-c-martin-c\xf3mo-esta-regla-aplicada-consistentemente-logra-transformar-un-sistema-legacy-sin-un-proyecto-de-refactorizaci\xf3n-expl\xedcito-cu\xe1les-son-sus-limitaciones",level:3},{value:"6. [Conectar] Relacion\xe1 el concepto de &quot;design stamina hypothesis&quot; mencionado en el m\xf3dulo 01 con el proceso de refactorizaci\xf3n de este m\xf3dulo. \xbfC\xf3mo las m\xe9tricas antes/despu\xe9s de la refactorizaci\xf3n (complejidad ciclom\xe1tica, cobertura, l\xedneas por clase) validan o refutan la hip\xf3tesis de Martin Fowler?",id:"6-conectar-relacion\xe1-el-concepto-de-design-stamina-hypothesis-mencionado-en-el-m\xf3dulo-01-con-el-proceso-de-refactorizaci\xf3n-de-este-m\xf3dulo-c\xf3mo-las-m\xe9tricas-antesdespu\xe9s-de-la-refactorizaci\xf3n-complejidad-ciclom\xe1tica-cobertura-l\xedneas-por-clase-validan-o-refutan-la-hip\xf3tesis-de-martin-fowler",level:3},{value:"7. [Conectar] La clase menciona &quot;caracterization tests&quot; de Michael Feathers. Conect\xe1 este concepto con la t\xe9cnica &quot;Golden Master Testing&quot; (tambi\xe9n conocido como &quot;Approval Testing&quot; de Llewellyn Falco, 2008). \xbfEn qu\xe9 se diferencian y cu\xe1ndo usar\xedas cada uno?",id:"7-conectar-la-clase-menciona-caracterization-tests-de-michael-feathers-conect\xe1-este-concepto-con-la-t\xe9cnica-golden-master-testing-tambi\xe9n-conocido-como-approval-testing-de-llewellyn-falco-2008-en-qu\xe9-se-diferencian-y-cu\xe1ndo-usar\xedas-cada-uno",level:3},{value:"8. [Cuestionar] \xbfEs siempre deseable reducir la complejidad ciclom\xe1tica y aumentar el n\xfamero de clases como muestran las m\xe9tricas de la clase? Investig\xe1 el concepto de &quot;carga cognitiva&quot; (cognitive load) en el dise\xf1o de software y argumentos de que 1 clase de 500 l\xedneas puede ser m\xe1s comprensible que 15 clases de 35 l\xedneas.",id:"8-cuestionar-es-siempre-deseable-reducir-la-complejidad-ciclom\xe1tica-y-aumentar-el-n\xfamero-de-clases-como-muestran-las-m\xe9tricas-de-la-clase-investig\xe1-el-concepto-de-carga-cognitiva-cognitive-load-en-el-dise\xf1o-de-software-y-argumentos-de-que-1-clase-de-500-l\xedneas-puede-ser-m\xe1s-comprensible-que-15-clases-de-35-l\xedneas",level:3},{value:"9. [Cuestionar] \xbfEs el orden de refactorizaci\xf3n propuesto en clase (SRP \u2192 DIP \u2192 OCP \u2192 LSP \u2192 ISP) el \xf3ptimo? Investig\xe1 posturas alternativas como la de Michael Feathers (&quot;primero romp\xe9 dependencias, despu\xe9s separ\xe1 responsabilidades&quot;) y argumentos para empezar por DIP en lugar de SRP.",id:"9-cuestionar-es-el-orden-de-refactorizaci\xf3n-propuesto-en-clase-srp--dip--ocp--lsp--isp-el-\xf3ptimo-investig\xe1-posturas-alternativas-como-la-de-michael-feathers-primero-romp\xe9-dependencias-despu\xe9s-separ\xe1-responsabilidades-y-argumentos-para-empezar-por-dip-en-lugar-de-srp",level:3},{value:"10. [Cuestionar] \xbfEs la refactorizaci\xf3n hacia SOLID siempre una decisi\xf3n t\xe9cnica o es fundamentalmente una decisi\xf3n de negocio? Investig\xe1 el concepto de &quot;Technical Debt Quadrant&quot; de Martin Fowler y c\xf3mo clasificar la deuda t\xe9cnica ayuda a decidir QU\xc9 refactorizar y qu\xe9 NO.",id:"10-cuestionar-es-la-refactorizaci\xf3n-hacia-solid-siempre-una-decisi\xf3n-t\xe9cnica-o-es-fundamentalmente-una-decisi\xf3n-de-negocio-investig\xe1-el-concepto-de-technical-debt-quadrant-de-martin-fowler-y-c\xf3mo-clasificar-la-deuda-t\xe9cnica-ayuda-a-decidir-qu\xe9-refactorizar-y-qu\xe9-no",level:3}];function d(e){const a={code:"code",h3:"h3",hr:"hr",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(a.h3,{id:"2-investigar-qu\xe9-es-el-patr\xf3n-strangler-fig-application-martin-fowler-2004-y-c\xf3mo-se-relaciona-con-la-refactorizaci\xf3n-incremental-hacia-solid-por-qu\xe9-es-preferible-a-una-reescritura-completa-incluso-si-el-objetivo-final-es-un-sistema-completamente-nuevo",children:'2. [Investigar] \xbfQu\xe9 es el patr\xf3n "Strangler Fig Application" (Martin Fowler, 2004) y c\xf3mo se relaciona con la refactorizaci\xf3n incremental hacia SOLID? \xbfPor qu\xe9 es preferible a una reescritura completa incluso si el objetivo final es un sistema completamente nuevo?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': El Strangler Fig Pattern (Fowler, "StranglerFigApplication", 2004) propone reemplazar un sistema legacy incrementalmente: en lugar de reescribir todo, se crea un nuevo sistema alrededor del viejo, migrando funcionalidades una por una. El "higuer\xf3n estrangulador" (planta que crece alrededor de un \xe1rbol hu\xe9sped y eventualmente lo reemplaza) es la met\xe1fora. Relaci\xf3n con SOLID: cada funcionalidad migrada se refactoriza hacia SOLID en el nuevo sistema. El viejo sistema se reduce gradualmente. Pasos: (1) Identificar un bounded context migrable (ej. "m\xf3dulo de usuarios"). (2) Construir el nuevo servicio con SRP/DIP/OCP. (3) Routing: el tr\xe1fico se divide entre viejo y nuevo seg\xfan la funcionalidad migrada. (4) Cuando el nuevo servicio cubre toda la funcionalidad del viejo, el viejo se apaga. Fowler argumenta que es preferible a reescritura completa porque: (a) el negocio recibe valor incremental (cada funcionalidad migrada est\xe1 en producci\xf3n), no hay "big freeze". (b) El riesgo es acotado: si la migraci\xf3n de una funcionalidad falla, solo esa funcionalidad se revierte. (c) La comparaci\xf3n A/B es posible: tr\xe1fico parcial al nuevo sistema permite detectar bugs progresivamente. (d) No se pierde conocimiento de negocio: se migra funcionalidad por funcionalidad, entendiendo el legacy en el proceso.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': Fowler desarroll\xf3 este patr\xf3n inspirado por proyectos en ThoughtWorks. Es la estrategia de refactorizaci\xf3n a nivel de sistema: cada funcionalidad migrada es un ejercicio de aplicar SOLID desde cero. Michael Feathers ("Working Effectively with Legacy Code") y Sam Newman ("Monolith to Microservices") lo recomiendan como la estrategia menos riesgosa para transformaciones grandes.']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"3-investigar-jb-rainsberger-public\xf3-integrated-tests-are-a-scam-2015-argumentando-que-las-pruebas-de-integraci\xf3n-son-una-p\xe9rdida-de-tiempo-comparadas-con-pruebas-unitarias-aisladas-c\xf3mo-se-conecta-este-argumento-con-dip-y-srp-por-qu\xe9-sin-dip-no-pod\xe9s-escribir-pruebas-unitarias-aisladas-que-cubran-el-mismo-comportamiento",children:'3. [Investigar] J.B. Rainsberger public\xf3 "Integrated Tests Are a Scam" (2015), argumentando que las pruebas de integraci\xf3n son una p\xe9rdida de tiempo comparadas con pruebas unitarias aisladas. \xbfC\xf3mo se conecta este argumento con DIP y SRP? \xbfPor qu\xe9 sin DIP no pod\xe9s escribir pruebas unitarias aisladas que cubran el mismo comportamiento?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': Rainsberger argumenta que las pruebas de integraci\xf3n son "una estafa" porque: son lentas, fr\xe1giles (se rompen por cambios no relacionados), dif\xedciles de diagnosticar, y costosas de mantener. La alternativa: pruebas unitarias aisladas con mocks que verifican contratos entre m\xf3dulos. Conexi\xf3n con DIP y SRP: ',(0,n.jsx)(a.strong,{children:"SRP"})," es el prerequisito: no pod\xe9s probar aisladamente una clase que mezcla validaci\xf3n, c\xe1lculo y persistencia. Necesit\xe1s separar responsabilidades en clases con contratos claros. ",(0,n.jsx)(a.strong,{children:"DIP"}),' es el habilitador: necesit\xe1s que la clase bajo test dependa de interfaces, no de implementaciones concretas, para poder mockearlas. Sin DIP, est\xe1s forzado a pruebas de integraci\xf3n porque la clase instancia sus dependencias. Rainsberger propone "contract tests": pruebas unitarias que verifican que la implementaci\xf3n cumple el contrato de la interfaz, + pruebas de integraci\xf3n m\xednimas que verifican que el wiring es correcto. La combinaci\xf3n DIP + SRP permite que el 90% de las pruebas sean unitarias (r\xe1pidas, estables) y solo el 10% sean de integraci\xf3n (verifican wiring). El art\xedculo de Rainsberger es un argumento econ\xf3mico a favor de SOLID: aplicar DIP y SRP REDUCE dr\xe1sticamente el costo de testing, que es uno de los mayores costos de mantenimiento.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': Rainsberger es un referente en TDD y sus argumentos refuerzan econ\xf3micamente a SOLID. Martin cit\xf3 trabajos similares: "la testabilidad es el primer beneficiario de SOLID". Rainsberger cuantifica: un sistema sin DIP/SRP gasta 80% de su presupuesto de testing en integraci\xf3n lenta; con DIP/SRP, gasta 20%.']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"4-investigar-qu\xe9-es-code-as-a-liability-c\xf3digo-como-pasivo-y-c\xf3mo-se-relaciona-con-la-decisi\xf3n-de-refactorizar-o-no-investig\xe1-la-postura-de-greg-young-y-alberto-brandolini-sobre-que-el-c\xf3digo-legacy-que-funciona-es-un-activo-no-un-pasivo-y-que-refactorizar-sin-necesidad-de-negocio-es-una-mala-inversi\xf3n",children:'4. [Investigar] \xbfQu\xe9 es "code as a liability" (c\xf3digo como pasivo) y c\xf3mo se relaciona con la decisi\xf3n de refactorizar o no? Investig\xe1 la postura de Greg Young y Alberto Brandolini sobre que el c\xf3digo legacy que funciona es un activo, no un pasivo, y que refactorizar sin necesidad de negocio es una mala inversi\xf3n.'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': Greg Young y Alberto Brandolini (creador de Event Storming) argumentan que el c\xf3digo legacy que funciona y genera valor es un ACTIVO, no un pasivo. La met\xe1fora de "deuda t\xe9cnica" de Cunningham es v\xe1lida, pero se abusa de ella: no todo c\xf3digo que no cumple SOLID es deuda; es deuda solo si ralentiza el desarrollo futuro. Brandolini: "el mejor c\xf3digo es el que se puede borrar; el segundo mejor es el que no necesita cambiarse". Refactorizar c\xf3digo que funciona, no tiene bugs y nunca se modifica, es una mala inversi\xf3n \u2014 convert\xeds un activo (c\xf3digo que genera valor sin costo) en un costo (horas de desarrollo sin retorno). Young (creador de CQRS) a\xf1ade: la refactorizaci\xf3n SOLID debe ser DRIVEN BY BUSINESS NEED, no driven by aesthetics. Si el negocio pide un feature que requiere modificar c\xf3digo legacy, refactoriz\xe1 ESE c\xf3digo para cumplir SOLID e implementar el feature. Pero no refactorices c\xf3digo que no vas a tocar. Esto conecta con YAGNI: SOLID es una inversi\xf3n en extensibilidad futura. Si el futuro no requiere extensi\xf3n en ese m\xf3dulo, la inversi\xf3n no se recupera. La postura: "el c\xf3digo legacy no es deuda t\xe9cnica; es un activo que quiz\xe1s tiene deuda t\xe9cnica asociada. Identific\xe1 cu\xe1l es cu\xe1l antes de refactorizar".']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': Brandolini y Young representan el pragmatismo extremo en DDD/Event Sourcing. Su cr\xedtica no es a SOLID sino al "refactoring for refactoring\'s sake". Martin mismo dijo: "no refactorices el ba\xf1o si solo viniste a arreglar la cocina".']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"5-conectar-conect\xe1-la-refactorizaci\xf3n-hacia-solid-con-el-concepto-de-the-boy-scout-rule-de-robert-c-martin-c\xf3mo-esta-regla-aplicada-consistentemente-logra-transformar-un-sistema-legacy-sin-un-proyecto-de-refactorizaci\xf3n-expl\xedcito-cu\xe1les-son-sus-limitaciones",children:'5. [Conectar] Conect\xe1 la refactorizaci\xf3n hacia SOLID con el concepto de "The Boy Scout Rule" de Robert C. Martin. \xbfC\xf3mo esta regla aplicada consistentemente logra transformar un sistema legacy sin un proyecto de refactorizaci\xf3n expl\xedcito? \xbfCu\xe1les son sus limitaciones?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': "The Boy Scout Rule" (Martin, "Clean Code", 2008): "Dej\xe1 el campamento m\xe1s limpio de como lo encontraste". Aplicado al c\xf3digo: cada vez que toc\xe1s un archivo para un feature o bug fix, dejalo un poco mejor de como estaba \u2014 extra\xe9 un m\xe9todo, renombr\xe1 una variable, reduc\xed un nivel de indentaci\xf3n. No refactorices el archivo completo; solo mejor\xe1 lo que ya est\xe1s tocando. C\xf3mo transforma un sistema legacy: (1) ',(0,n.jsx)(a.strong,{children:"Efecto compuesto"}),": si 5 desarrolladores aplican la regla por 6 meses, los archivos m\xe1s modificados (los que m\xe1s valor de negocio tienen) gradualmente convergen hacia SOLID sin un proyecto expl\xedcito. (2) ",(0,n.jsx)(a.strong,{children:"Costo marginal cero"}),': el costo de la mejora est\xe1 incluido en el costo del feature \u2014 no hay partida presupuestaria separada para "refactorizaci\xf3n". (3) ',(0,n.jsx)(a.strong,{children:"Alienaci\xf3n con el negocio"}),": solo se mejora c\xf3digo que el negocio valora (porque se modifica para features que el negocio pide). Limitaciones: (a) solo mejora archivos que se tocan \u2014 un m\xf3dulo legacy estable puede permanecer legacy para siempre. (b) Las mejoras son locales (extract method, rename) pero no arquitect\xf3nicas (cambiar de herencia a composici\xf3n requiere tocar m\xfaltiples archivos simult\xe1neamente). (c) Requiere disciplina de equipo y que los code reviews exijan la regla. (d) Para cambios estructurales grandes (separar un monolito en microservicios), la Boy Scout Rule es insuficiente \u2014 se necesita Strangler Fig o Mikado."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),": Martin dise\xf1\xf3 la Boy Scout Rule como la estrategia de refactorizaci\xf3n de menor fricci\xf3n. No requiere aprobaci\xf3n de gerencia ni presupuesto dedicado. Es SOLID aplicado granularmente: un extract method por d\xeda = SRP incremental; un introduce interface por semana = DIP incremental."]}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"6-conectar-relacion\xe1-el-concepto-de-design-stamina-hypothesis-mencionado-en-el-m\xf3dulo-01-con-el-proceso-de-refactorizaci\xf3n-de-este-m\xf3dulo-c\xf3mo-las-m\xe9tricas-antesdespu\xe9s-de-la-refactorizaci\xf3n-complejidad-ciclom\xe1tica-cobertura-l\xedneas-por-clase-validan-o-refutan-la-hip\xf3tesis-de-martin-fowler",children:'6. [Conectar] Relacion\xe1 el concepto de "design stamina hypothesis" mencionado en el m\xf3dulo 01 con el proceso de refactorizaci\xf3n de este m\xf3dulo. \xbfC\xf3mo las m\xe9tricas antes/despu\xe9s de la refactorizaci\xf3n (complejidad ciclom\xe1tica, cobertura, l\xedneas por clase) validan o refutan la hip\xf3tesis de Martin Fowler?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': La Design Stamina Hypothesis (Fowler, 2007) propone que el buen dise\xf1o tiene retorno de inversi\xf3n positivo: el esfuerzo extra de dise\xf1ar bien se paga con creces en mantenimiento m\xe1s barato. Las m\xe9tricas antes/despu\xe9s de la refactorizaci\xf3n de este m\xf3dulo la validan: antes de SOLID: 1 clase de 1200 l\xedneas, complejidad ciclom\xe1tica 18, 0% cobertura, 8 responsabilidades mezcladas. Agregar un feature (nuevo tipo de cliente) tomaba 30 minutos y romp\xeda otro feature (alto costo de cambio). Despu\xe9s de SOLID: 14 clases de 45 l\xedneas promedio, complejidad 3, 92% cobertura. Agregar el mismo feature toma 5 minutos y no rompe nada. El retorno de inversi\xf3n: invertiste X horas en refactorizar \u2192 cada cambio futuro cuesta 80% menos. Si el sistema recibe 20 cambios en un a\xf1o, la inversi\xf3n se recupera en semanas. Fowler usa exactamente este argumento: los sistemas mal dise\xf1ados TIENEN un l\xedmite de complejidad m\xe1s all\xe1 del cual colapsan. Las m\xe9tricas cuantifican ese l\xedmite: una clase con complejidad > 50 es inmantenible; un sistema con 0% cobertura no se puede modificar sin miedo. La refactorizaci\xf3n aleja al sistema del "colapso" y lo acerca a la "zona de stamina". Las m\xe9tricas no refutan la hip\xf3tesis; la confirman mostrando que la inversi\xf3n en dise\xf1o mejora indicadores que predicen menor costo de cambio.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': Fowler populariz\xf3 la hip\xf3tesis pero fueron estudios como los de Capers Jones (2011) y el "State of DevOps Report" los que la validaron con datos: equipos con buena arquitectura entregan 2x m\xe1s features con 50% menos bugs.']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"7-conectar-la-clase-menciona-caracterization-tests-de-michael-feathers-conect\xe1-este-concepto-con-la-t\xe9cnica-golden-master-testing-tambi\xe9n-conocido-como-approval-testing-de-llewellyn-falco-2008-en-qu\xe9-se-diferencian-y-cu\xe1ndo-usar\xedas-cada-uno",children:'7. [Conectar] La clase menciona "caracterization tests" de Michael Feathers. Conect\xe1 este concepto con la t\xe9cnica "Golden Master Testing" (tambi\xe9n conocido como "Approval Testing" de Llewellyn Falco, 2008). \xbfEn qu\xe9 se diferencian y cu\xe1ndo usar\xedas cada uno?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),": Ambos son t\xe9cnicas para crear una red de seguridad en c\xf3digo sin pruebas, pero difieren en enfoque: ",(0,n.jsx)(a.strong,{children:"Characterization Tests"})," (Feathers, 2004): Escrib\xeds pruebas individuales para comportamientos espec\xedficos. Ejecut\xe1s el c\xf3digo con una entrada, captur\xe1s la salida, y la convert\xeds en assertion. Son at\xf3micos: cubren un m\xe9todo o funcionalidad. ",(0,n.jsx)(a.strong,{children:"Golden Master Testing"}),' (Falco / Approval Tests, 2008): Captur\xe1s la salida COMPLETA de un escenario complejo (archivo, reporte, respuesta HTTP completa) y la guard\xe1s como "golden master". En futuras ejecuciones, compar\xe1s la salida completa contra el golden master. Si cambia, el test falla y revis\xe1s si el cambio es intencional o bug. Diferencias: Characterization Tests son espec\xedficos (fallan solo para el comportamiento que cambi\xf3); Golden Master es hol\xedstico (falla para CUALQUIER cambio en la salida, incluso cambios triviales de formato). \xbfCu\xe1ndo usar cada uno? Characterization Tests: cuando pod\xe9s identificar comportamientos individuales y quer\xe9s documentarlos como pruebas. Golden Master: cuando el sistema genera outputs complejos (reportes, PDFs, APIs con respuestas grandes) y quer\xe9s una red de seguridad r\xe1pida sin escribir 100 assertions individuales. Para refactorizaci\xf3n SOLID: empezar con Golden Master para el output del God Object (capturar comportamiento completo del ',(0,n.jsx)(a.code,{children:"processOrder"})," de 200 l\xedneas), luego escribir Characterization Tests sobre los m\xe9todos extra\xeddos, y finalmente reemplazar ambos con pruebas unitarias puras despu\xe9s de aplicar SRP/DIP."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),": Feathers y Falco resolvieron el mismo problema desde \xe1ngulos complementarios. Feathers es quir\xfargico (prueba por prueba); Falco es de cobertura (golden master captura todo). La combinaci\xf3n de ambos es la red de seguridad m\xe1s r\xe1pida para empezar una refactorizaci\xf3n SOLID."]}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"8-cuestionar-es-siempre-deseable-reducir-la-complejidad-ciclom\xe1tica-y-aumentar-el-n\xfamero-de-clases-como-muestran-las-m\xe9tricas-de-la-clase-investig\xe1-el-concepto-de-carga-cognitiva-cognitive-load-en-el-dise\xf1o-de-software-y-argumentos-de-que-1-clase-de-500-l\xedneas-puede-ser-m\xe1s-comprensible-que-15-clases-de-35-l\xedneas",children:'8. [Cuestionar] \xbfEs siempre deseable reducir la complejidad ciclom\xe1tica y aumentar el n\xfamero de clases como muestran las m\xe9tricas de la clase? Investig\xe1 el concepto de "carga cognitiva" (cognitive load) en el dise\xf1o de software y argumentos de que 1 clase de 500 l\xedneas puede ser m\xe1s comprensible que 15 clases de 35 l\xedneas.'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': La m\xe9trica de "m\xe1s clases = mejor" tiene detractores. John Ousterhout ("A Philosophy of Software Design", 2018) argumenta que: ',(0,n.jsx)(a.strong,{children:"Carga cognitiva"}),": 1 clase de 500 l\xedneas que implementa una m\xe1quina de estados finita con 10 estados es m\xe1s f\xe1cil de entender que 11 clases (1 por estado + 1 orquestador) porque el flujo completo es visible en un solo archivo. El lector no necesita reconstruir mentalmente la interacci\xf3n entre 11 archivos. ",(0,n.jsx)(a.strong,{children:"Deep modules"}),': Ousterhout defiende "m\xf3dulos profundos" \u2014 interfaces peque\xf1as con implementaciones complejas \u2014 sobre "m\xf3dulos superficiales" \u2014 interfaces peque\xf1as con implementaciones triviales. 15 clases de 35 l\xedneas, cada una con una interfaz de 1 m\xe9todo, son "m\xf3dulos superficiales": mucha estructura, poca sustancia. ',(0,n.jsx)(a.strong,{children:"Costo de la navegaci\xf3n"}),": en un IDE moderno, saltar entre 15 archivos para entender un caso de uso tiene un costo cognitivo REAL (interrupciones de flujo, p\xe9rdida de contexto). ",(0,n.jsx)(a.strong,{children:"Estudio de caso"}),': el c\xf3digo legacy de la clase con 1200 l\xedneas ciertamente era un problema (God Class). Pero la soluci\xf3n no es "atomizar en N clases" sino encontrar el nivel correcto de granularidad. La m\xe9trica "clases promedio de 45 l\xedneas" puede ser tan problem\xe1tica como "clases de 1200 l\xedneas" si la granularidad es artificial. La m\xe9trica correcta no es l\xedneas por clase sino "\xbfpuedo entender este m\xf3dulo sin abrir otros archivos?". Si para entender c\xf3mo se procesa una orden necesit\xe1s 8 archivos, la refactorizaci\xf3n reemplaz\xf3 spaghetti code con ravioli code.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': Ousterhout no est\xe1 en contra de SOLID sino de la aplicaci\xf3n dogm\xe1tica de "clases peque\xf1as". Su libro es un contrapunto a Clean Code y Clean Architecture: el objetivo es complejidad manejable, no l\xedneas por clase.']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"9-cuestionar-es-el-orden-de-refactorizaci\xf3n-propuesto-en-clase-srp--dip--ocp--lsp--isp-el-\xf3ptimo-investig\xe1-posturas-alternativas-como-la-de-michael-feathers-primero-romp\xe9-dependencias-despu\xe9s-separ\xe1-responsabilidades-y-argumentos-para-empezar-por-dip-en-lugar-de-srp",children:'9. [Cuestionar] \xbfEs el orden de refactorizaci\xf3n propuesto en clase (SRP \u2192 DIP \u2192 OCP \u2192 LSP \u2192 ISP) el \xf3ptimo? Investig\xe1 posturas alternativas como la de Michael Feathers ("primero romp\xe9 dependencias, despu\xe9s separ\xe1 responsabilidades") y argumentos para empezar por DIP en lugar de SRP.'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': La clase propone SRP \u2192 DIP \u2192 OCP \u2192 LSP \u2192 ISP. Feathers propone el orden inverso en "Working Effectively with Legacy Code" (2004): ',(0,n.jsx)(a.strong,{children:"1\xba DIP primero"}),": identific\xe1 dependencias concretas (",(0,n.jsx)(a.code,{children:"new MySQLDatabase()"}),") y cre\xe1 interfaces + seams. Esto permite mockear en pruebas. Sin esto, cualquier cambio es peligroso porque no ten\xe9s red de seguridad. ",(0,n.jsx)(a.strong,{children:"2\xba Romp\xe9 dependencias"}),": extra\xe9 m\xe9todos, par\xe1metros, y subclases testeables. ",(0,n.jsx)(a.strong,{children:"3\xba SRP despu\xe9s"}),": una vez que pod\xe9s probar, separ\xe1 responsabilidades. El argumento de Feathers: no pod\xe9s separar responsabilidades sin pruebas que verifiquen que no rompiste nada. Las pruebas requieren DIP (poder inyectar mocks). Por lo tanto, DIP viene antes que SRP en legacy. ",(0,n.jsx)(a.strong,{children:"Contraste con la clase"}),': la clase asume que empez\xe1s con characterization tests (que no requieren DIP \u2014 capturan comportamiento "as-is" sin modificar nada). Con characterization tests, pod\xe9s hacer SRP primero porque la red de seguridad ya existe sin modificar dependencias. Feathers asume que NO ten\xe9s characterization tests y que tu primera acci\xf3n es crear seams (DIP). Ambos son v\xe1lidos en diferentes contextos: si ten\xe9s caracterization tests \u2192 SRP primero (la clase). Si no ten\xe9s pruebas ni pod\xe9s escribirlas sin modificar c\xf3digo \u2192 DIP primero (Feathers). La discusi\xf3n es sobre el orden pr\xe1ctico, no sobre el orden l\xf3gico de los principios.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),": Feathers trabaj\xf3 con c\xf3digo legacy EXTREMO (sin pruebas, sin interfaces, con dependencias hardcodeadas). Su orden DIP-first es pragm\xe1tico: no pod\xe9s separar lo que no pod\xe9s probar. La clase asume un entorno m\xe1s controlado con caracterization tests disponibles."]}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"10-cuestionar-es-la-refactorizaci\xf3n-hacia-solid-siempre-una-decisi\xf3n-t\xe9cnica-o-es-fundamentalmente-una-decisi\xf3n-de-negocio-investig\xe1-el-concepto-de-technical-debt-quadrant-de-martin-fowler-y-c\xf3mo-clasificar-la-deuda-t\xe9cnica-ayuda-a-decidir-qu\xe9-refactorizar-y-qu\xe9-no",children:'10. [Cuestionar] \xbfEs la refactorizaci\xf3n hacia SOLID siempre una decisi\xf3n t\xe9cnica o es fundamentalmente una decisi\xf3n de negocio? Investig\xe1 el concepto de "Technical Debt Quadrant" de Martin Fowler y c\xf3mo clasificar la deuda t\xe9cnica ayuda a decidir QU\xc9 refactorizar y qu\xe9 NO.'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': Fowler propuso el "Technical Debt Quadrant" (2009) que clasifica la deuda en 4 cuadrantes seg\xfan dos ejes: \xbffue deliberada o inadvertida? \xbfEs prudente o imprudente? ',(0,n.jsx)(a.strong,{children:"Cuadrante 1 (Deliberada + Prudente)"}),': "Sabemos que debemos refactorizar, pero necesitamos el feature ahora y lo pagaremos despu\xe9s". Es deuda estrat\xe9gica, con un plan de pago. ',(0,n.jsx)(a.strong,{children:"Cuadrante 2 (Inadvertida + Imprudente)"}),': "No sab\xedamos que est\xe1bamos haciendo mal dise\xf1o". Es ignorancia. ',(0,n.jsx)(a.strong,{children:"Cuadrante 3 (Deliberada + Imprudente)"}),': "No tenemos tiempo para dise\xf1o". Es la peor \u2014 sab\xe9s que es malo y lo hac\xe9s igual sin plan. ',(0,n.jsx)(a.strong,{children:"Cuadrante 4 (Inadvertida + Prudente)"}),': "Ahora que entendemos el dominio, nos damos cuenta de que el dise\xf1o deber\xeda ser diferente". Es aprendizaje \u2014 el c\xf3digo es legacy leg\xedtimo. Esta clasificaci\xf3n ayuda a decidir QU\xc9 refactorizar CU\xc1NDO: Cuadrante 1: refactorizar seg\xfan el plan acordado con el negocio. Cuadrante 3: refactorizar urgentemente \u2014 es deuda t\xf3xica. Cuadrante 2: refactorizar progresivamente con Boy Scout Rule. Cuadrante 4: refactorizar solo si el costo de cambio actual lo justifica (quiz\xe1s el dise\xf1o "viejo" sigue siendo adecuado). La refactorizaci\xf3n SOLID es una decisi\xf3n de negocio cuando afecta la capacidad de entregar features. Si la deuda es Cuadrante 3 (imprudente), es responsabilidad t\xe9cnica comunicarlo al negocio: "si no refactorizamos, el pr\xf3ximo feature tomar\xe1 3 semanas en lugar de 3 d\xedas". Si es Cuadrante 4 (aprendizaje), es una decisi\xf3n t\xe9cnica evaluar si el nuevo dise\xf1o SOLID realmente reduce el costo de cambio o solo satisface una est\xe9tica arquitect\xf3nica.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),": Fowler present\xf3 el cuadrante para des-culpabilizar la deuda t\xe9cnica: no toda deuda es mala; la deuda estrat\xe9gica (Cuadrante 1) es una herramienta de negocio. SOLID es la disciplina para mantener la deuda en Cuadrantes 1 y 4, y eliminar la de Cuadrantes 2 y 3."]})]})}function u(e={}){const{wrapper:a}={...(0,i.R)(),...e.components};return a?(0,n.jsx)(a,{...e,children:(0,n.jsx)(d,{...e})}):d(e)}},28453(e,a,o){o.d(a,{R:()=>r,x:()=>c});var s=o(96540);const n={},i=s.createContext(n);function r(e){const a=s.useContext(i);return s.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function c(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:r(e.components),s.createElement(i.Provider,{value:a},e.children)}}}]);